INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁镇", "aliases": ["明英宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明英宗，宣德10年（1435年）正月，朱祁镇即皇帝位。", "biography": null, "status": "draft", "id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf"}, {"name": "石彪", "aliases": ["遊擊將軍石彪"], "era": "明", "birth_year": null, "death_year": null, "description": "石彪奉命巡视边防。", "biography": null, "status": "draft", "id": "b3dd53cf-1dfa-5406-ba6a-f6de1d1bab3d"}, {"name": "孛来", "aliases": ["孛來"], "era": "明", "birth_year": null, "death_year": null, "description": "孛来率部进攻宁夏。", "biography": null, "status": "draft", "id": "002b89e8-be8d-5e7f-9365-e517b45d0c6d"}, {"name": "叶盛", "aliases": ["葉盛"], "era": "明", "birth_year": null, "death_year": null, "description": "叶盛以巡抚两广身份指挥作战。", "biography": null, "status": "draft", "id": "9adb825c-b572-5e70-8ab1-156093ec5501"}, {"name": "方瑛", "aliases": ["參將方瑛"], "era": "明", "birth_year": null, "death_year": null, "description": "方瑛参与贵州战事。", "biography": null, "status": "draft", "id": "02981879-a0e2-5f34-81d2-beadecd41264"}, {"name": "石亨", "aliases": ["都督石亨"], "era": "明", "birth_year": null, "death_year": null, "description": "石亨奉命统领京营兵。", "biography": null, "status": "draft", "id": "9892b251-a863-5d74-9c23-727ee42a25de"}]'::jsonb)
