INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明英宗在南郊祭祀天地", "description": "天顺三年正月乙未，明英宗朱祁镇在南郊举行祭祀天地的大典。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年正月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9e369747-ff55-5e35-a3fd-3ce0959e8248"}, {"title": "石彪、杨信在安边营击败孛来所部", "description": "天顺三年正月甲辰，定远伯石彪和彰武伯杨信在安边营击败孛来所部。都督佥事周贤、都指挥李鉴在交战中阵亡。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年正月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9baee551-fdac-5b43-a499-f7401db4e15b"}, {"title": "石彪从定远伯进封为定远侯", "description": "明廷将定远伯石彪进封为定远侯。《英宗后纪》将此事写在天顺三年正月战报之后，卷末校记所引功臣世表及《英宗实录》记在四月己巳。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年四月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3e4d8ac1-72f8-54bc-9ef9-da43a70f62d8"}, {"title": "明廷派御史和宦官到广东采珠", "description": "天顺三年二月丁卯，朝廷派遣御史和宫中宦官到广东采集珍珠。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年二月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "49c1272d-edb5-5ea0-a6f6-c9f6fe51b8f9"}, {"title": "叶盛在泷水击败起事瑶民", "description": "天顺三年四月壬子，巡抚两广的佥都御史叶盛率部击败泷水一带起事的瑶民。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年四月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7e7e1801-46f7-5699-9e07-3b8bcf9a6521"}, {"title": "南和侯方瑛在贵州击败起事苗民", "description": "天顺三年四月己巳，南和侯方瑛在贵州率部击败起事的苗民。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年四月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a193f574-6f14-50d8-980b-c38c82f17b08"}, {"title": "明廷恢复八月召巡抚进京议事", "description": "天顺三年六月辛酉，朝廷恢复召各地巡抚到京师议事的安排，指定八月在京师集合。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年六月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "741043b3-367e-5c58-88b0-2749e559a96b"}, {"title": "石彪获罪，被关进锦衣卫监狱", "description": "天顺三年八月庚戌，明廷认定石彪有罪，将他关进锦衣卫监狱。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年八月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bf1d51bf-9a39-5ad5-9f1e-772dfcb4da5d"}, {"title": "明廷禁止文武大臣、监察官与锦衣卫官等私下交接", "description": "天顺三年八月己未，朝廷禁止文武大臣、给事中、御史以及锦衣卫官员私下往来。违令者依铁榜所列的规定论罪。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年八月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bcbb4116-300d-52b7-bfa9-bbc45439a305"}, {"title": "明廷豁免湖广灾区秋粮", "description": "天顺三年八月乙亥，朝廷免除湖广受灾地区应缴的秋粮。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年八月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7399655e-0f69-5f92-8c2b-85592d6b444d"}, {"title": "明英宗前往南海子", "description": "天顺三年十月己未，明英宗朱祁镇前往南海子。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年十月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "301aea07-bb2c-5557-a2f5-7f5234964b4a"}, {"title": "石亨获罪被罢免", "description": "天顺三年十月庚午，本纪记石亨因获罪被罢免。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年十月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "107b7098-3209-5245-ac5f-9cddcdc04016"}, {"title": "明廷准许冒领迎复之功者自首改正", "description": "天顺三年十月，明廷准许冒报有功于英宗复位的人主动承认并改正。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "563193d3-3576-5e26-9a09-4acee610edb2"}, {"title": "明廷规定每年霜降由司法衙门会同廷臣审录囚案", "description": "天顺三年十月，朝廷命司法衙门会同廷臣，在每年霜降审查在押人员的案件。本纪记这后来成为常例。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1e225e85-6428-5efd-a9af-8f6a4c35efb1"}, {"title": "明廷赈济湖广饥民", "description": "天顺三年十一月癸巳，明廷赈济湖广的饥民。", "start_year": 1459, "end_year": 1459, "time_original": "天顺三年十一月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d21fea64-111c-5a0d-889d-e78d9d38ba5b"}, {"title": "哈密、琉球中山、锡兰山和满剌加入贡", "description": "天顺三年，哈密、琉球中山、锡兰山和满剌加入贡。本纪原文将琉球中山写作“疏球中山”。 按原历纪年，事情发生在公元1459至1460年之间。", "start_year": null, "end_year": null, "time_original": "天顺三年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a41ccb20-b293-590e-89b3-5858e7725f17"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

